<?php
$dir=__DIR__.'/imagenes';$files=[];if(is_dir($dir)){foreach(scandir($dir) as $f){if(preg_match('/\\.(jpg|jpeg|png|gif|webp)$/i',$f)&&is_file($dir.'/'.$f))$files[]=$f;}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ejercicio 05 | Galería</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">P</span> PWATAREA3</a><a class="back" href="../index.php">← Volver al inicio</a></header><main class="page-wrap"><span class="eyebrow">EJERCICIO 05</span><section class="panel"><h1>Galería de imágenes</h1><p class="muted">PHP lee automáticamente las imágenes de la carpeta <b>ejercicio05/imagenes</b>. Añade archivos JPG, PNG, GIF o WEBP para que aparezcan aquí.</p><div class="gallery"><?php foreach($files as $f): ?><figure><img src="imagenes/<?=rawurlencode($f)?>" alt="<?=htmlspecialchars($f)?>"><figcaption class="small"><?=htmlspecialchars($f)?></figcaption></figure><?php endforeach; ?></div><?php if(!$files): ?><p class="notice">Todavía no hay imágenes. Coloca fotografías dentro de la carpeta <b>imagenes</b>.</p><?php endif; ?></section></main></body></html>